# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
import logging

import torch
import triton
import triton.language as tl

from flag_gems.runtime import torch_device_fn
from flag_gems.utils import libentry, pointwise_dynamic

logger = logging.getLogger(__name__)

NUM_SIPS = 24

# GCU400 override of the generic pointwise_dynamic implementation.
# cosh_backward(grad, x) = grad * sinh(x) is a two-input streaming elementwise
# op, so the only tuning knobs are the tile ladder and the sinh body shape.
# The generic pointwise path launches a small number of CTAs; the flat
# grid-stride kernels below spread the tiles over NUM_SIPS * 2 programs, which
# is the structure that put the sinh family (cosh.py / sinh.py / sigmoid.py)
# at the memory-copy floor on GCU400.


@libentry()
@triton.jit(do_not_specialize=["N_total"])
def cosh_backward_flat_kernel(
    g_ptr,
    x_ptr,
    out_ptr,
    N_total,
    BLOCK: tl.constexpr,
    EXACT: tl.constexpr,
    DISTRIBUTED: tl.constexpr,
):
    pid = tl.program_id(0)
    num_pids = tl.num_programs(0)
    arange = tl.arange(0, BLOCK)

    if EXACT:
        # Dispatched when N_total % BLOCK == 0: dropping the boundary mask and
        # its predication is bit-identical for in-range accesses.
        num_blocks = N_total // BLOCK
        for block_id in tl.range(pid, num_blocks, num_pids):
            off = block_id * BLOCK + arange
            g = tl.load(g_ptr + off, eviction_policy="evict_first").to(tl.float32)
            x = tl.load(x_ptr + off, eviction_policy="evict_first").to(tl.float32)
            if DISTRIBUTED:
                # Splitting the final scale over both exponential terms removes
                # one elementwise pass on 16-bit streams (sinh.py measurement).
                out = (tl.exp(x) * 0.5 - tl.exp(-x) * 0.5) * g
            else:
                out = 0.5 * (tl.exp(x) - tl.exp(-x)) * g
            tl.store(out_ptr + off, out)
    else:
        num_blocks = (N_total + BLOCK - 1) // BLOCK
        for block_id in tl.range(pid, num_blocks, num_pids):
            off = block_id * BLOCK + arange
            mask = off < N_total
            g = tl.load(g_ptr + off, mask=mask, eviction_policy="evict_first").to(
                tl.float32
            )
            x = tl.load(x_ptr + off, mask=mask, eviction_policy="evict_first").to(
                tl.float32
            )
            if DISTRIBUTED:
                out = (tl.exp(x) * 0.5 - tl.exp(-x) * 0.5) * g
            else:
                out = 0.5 * (tl.exp(x) - tl.exp(-x)) * g
            tl.store(out_ptr + off, out, mask=mask)


@pointwise_dynamic(promotion_methods=[(0, "INT_TO_FLOAT")])
@triton.jit
def _cosh_backward_generic(grad, x):
    # sinh(x) = (exp(x) - exp(-x)) / 2, evaluated in fp32 like the common path
    grad_f32 = grad.to(tl.float32)
    x_f32 = x.to(tl.float32)
    return grad_f32 * (tl.exp(x_f32) - tl.exp(-x_f32)) * 0.5


def _choose_block(N_total, itemsize):
    # Same tile ladder shape as sinh.py (a sibling two-exp streaming op); the
    # second operand doubles the loaded bytes per tile, so the ladder is
    # re-swept on the core shapes in the probe harness before being frozen.
    if N_total <= 8192:
        return triton.next_power_of_2(N_total)
    if itemsize <= 2:
        if N_total <= 1 << 18:
            return 8192
        if N_total <= 1 << 21:
            return 16384
        if N_total <= 1 << 24:
            return 32768
        if N_total > 1 << 28:
            return 131072
        return 65536
    if N_total <= 65536:
        return 8192
    if N_total <= 524288:
        return 32768
    return 65536


def _launch_cosh_backward_flat(grad, x, out, N_total, itemsize, dtype):
    BLOCK = _choose_block(N_total, itemsize)
    grid_size = min(triton.cdiv(N_total, BLOCK), NUM_SIPS * 2)
    is_f32 = dtype == torch.float32
    num_warps = 4 if is_f32 else 2
    # The external llvm converter intermittently fails on cold compiles; retry
    # the launch so a transient converter flake does not surface as an error
    # (same mitigation as sinh.py / atan2_.py).
    for attempt in range(3):
        try:
            with torch_device_fn.device(grad.device):
                cosh_backward_flat_kernel[(grid_size,)](
                    grad,
                    x,
                    out,
                    N_total,
                    BLOCK=BLOCK,
                    EXACT=(N_total % BLOCK == 0),
                    DISTRIBUTED=not is_f32,
                    num_warps=num_warps,
                )
            return out
        except Exception as exc:
            if attempt == 2:
                raise
            logger.warning(
                "cosh_backward flat kernel launch failed (attempt %d): %s",
                attempt + 1,
                exc,
            )


def cosh_backward(grad, x):
    logger.debug("GEMS_ENFLAME COSH_BACKWARD")
    if (
        grad.dtype not in (torch.float16, torch.bfloat16, torch.float32)
        or grad.dtype != x.dtype
    ):
        return _cosh_backward_generic(grad, x)
    inp_grad = grad if grad.is_contiguous() else grad.contiguous()
    inp_x = x if x.is_contiguous() else x.contiguous()
    out = torch.empty_like(inp_x)
    N_total = inp_x.numel()
    if N_total == 0:
        return out

    _launch_cosh_backward_flat(
        inp_grad, inp_x, out, N_total, inp_x.element_size(), inp_x.dtype
    )
    return out
